#[derive(Debug)]
struct DType {
    kind: char,
    itemsize: usize,
    alignment: usize,
    name: String,
}

fn numpy_dtype(type_spec: &str) -> DType {
    match type_spec {
        "int8" => DType {
            kind: 'i',
            itemsize: 1,
            alignment: 1,
            name: "int8".to_string(),
        },
        "int16" => DType {
            kind: 'i',
            itemsize: 2,
            alignment: 2,
            name: "int16".to_string(),
        },
        "int32" => DType {
            kind: 'i',
            itemsize: 4,
            alignment: 4,
            name: "int32".to_string(),
        },
        "int64" => DType {
            kind: 'i',
            itemsize: 8,
            alignment: 8,
            name: "int64".to_string(),
        },
        "float32" => DType {
            kind: 'f',
            itemsize: 4,
            alignment: 4,
            name: "float32".to_string(),
        },
        "float64" => DType {
            kind: 'f',
            itemsize: 8,
            alignment: 8,
            name: "float64".to_string(),
        },
        "bool" => DType {
            kind: 'b',
            itemsize: 1,
            alignment: 1,
            name: "bool".to_string(),
        },
        _ => panic!("Invalid type specification: {}", type_spec),
    }
}

fn main() {
    // Example usage
    let dtype = numpy_dtype("int32");
    println!("{:?}", dtype);
}